00070 unsigned Scheduler::getSplitDataId( int jobId ) const
00071 {
00072   if( m_numSplitThreads > 1 && m_hasParallelBuffer )
00073   {
00074     int splitJobId = jobId == CURR_THREAD_ID ? g_splitJobId : jobId;
00075 
00076     return ( g_wppThreadId * NUM_RESERVERD_SPLIT_JOBS ) + splitJobId;
00077   }
00078   else
00079   {
00080     return 0;
00081   }
00082 }
