00203 void Picture::create( const ChromaFormat &_chromaFormat, const Size &size, const unsigned _maxCUSize, const unsigned _margin, const bool _decoder, const int _layerId, const bool gopBasedTemporalFilterEnabled )
00204 {
00205   layerId = _layerId;
00206   UnitArea::operator=( UnitArea( _chromaFormat, Area( Position{ 0, 0 }, size ) ) );
00207   margin            =  MAX_SCALING_RATIO*_margin;
00208   const Area a      = Area( Position(), size );
00209   M_BUFS( 0, PIC_RECONSTRUCTION ).create( _chromaFormat, a, _maxCUSize, margin, MEMORY_ALIGN_DEF_SIZE );
00210   M_BUFS( 0, PIC_RECON_WRAP ).create( _chromaFormat, a, _maxCUSize, margin, MEMORY_ALIGN_DEF_SIZE );
00211 
00212   if( !_decoder )
00213   {
00214     M_BUFS( 0, PIC_ORIGINAL ).    create( _chromaFormat, a );
00215     M_BUFS( 0, PIC_TRUE_ORIGINAL ). create( _chromaFormat, a );
00216     if(gopBasedTemporalFilterEnabled)
00217     {
00218       M_BUFS( 0, PIC_FILTERED_ORIGINAL ). create( _chromaFormat, a );
00219     }
00220   }
00221 #if !KEEP_PRED_AND_RESI_SIGNALS
00222   m_ctuArea = UnitArea( _chromaFormat, Area( Position{ 0, 0 }, Size( _maxCUSize, _maxCUSize ) ) );
00223 #endif
00224   m_hashMap.clearAll();
00225 }
00226 
00227 void Picture::destroy()
00228 {
00229 #if ENABLE_SPLIT_PARALLELISM
00230   for( int jId = 0; jId < PARL_SPLIT_MAX_NUM_THREADS; jId++ )
00231 #endif
00232   {
00233     for (uint32_t t = 0; t < NUM_PIC_TYPES; t++)
00234     {
00235       M_BUFS(jId, t).destroy();
00236     }
00237     m_hashMap.clearAll();
00238     if (cs)
00239     {
00240       cs->destroy();
00241       delete cs;
00242       cs = nullptr;
00243     }
00244 
00245     for (auto &ps: slices)
00246     {
00247       delete ps;
00248     }
00249     slices.clear();
00250 
00251     for (auto &psei: SEIs)
00252     {
00253       delete psei;
00254     }
00255     SEIs.clear();
00256 
00257     if (m_spliceIdx)
00258     {
00259       delete[] m_spliceIdx;
00260       m_spliceIdx = NULL;
00261     }
00262   }
00263 }
