00265 void Picture::createTempBuffers( const unsigned _maxCUSize )
00266 {
00267 #if KEEP_PRED_AND_RESI_SIGNALS
00268   const Area a( Position{ 0, 0 }, lumaSize() );
00269 #else
00270   const Area a = m_ctuArea.Y();
00271 #endif
00272 
00273 #if ENABLE_SPLIT_PARALLELISM
00274   scheduler.startParallel();
00275 
00276   for( int jId = 0; jId < scheduler.getNumPicInstances(); jId++ )
00277 #endif
00278   {
00279     M_BUFS( jId, PIC_PREDICTION                   ).create( chromaFormat, a,   _maxCUSize );
00280     M_BUFS( jId, PIC_RESIDUAL                     ).create( chromaFormat, a,   _maxCUSize );
00281 #if ENABLE_SPLIT_PARALLELISM
00282     if (jId > 0)
00283     {
00284       M_BUFS(jId, PIC_RECONSTRUCTION).create(chromaFormat, Y(), _maxCUSize, margin, MEMORY_ALIGN_DEF_SIZE);
00285     }
00286 #endif
00287   }
00288 
00289   if (cs)
00290   {
00291     cs->rebindPicBufs();
00292   }
00293 }
00294 
00295 void Picture::destroyTempBuffers()
00296 {
00297 #if ENABLE_SPLIT_PARALLELISM
00298   scheduler.finishParallel();
00299 
00300   for( int jId = 0; jId < scheduler.getNumPicInstances(); jId++ )
00301 #endif
00302   {
00303     for (uint32_t t = 0; t < NUM_PIC_TYPES; t++)
00304     {
00305       if (t == PIC_RESIDUAL || t == PIC_PREDICTION)
00306       {
00307         M_BUFS(jId, t).destroy();
00308       }
00309 #if ENABLE_SPLIT_PARALLELISM
00310       if (t == PIC_RECONSTRUCTION && jId > 0)
00311       {
00312         M_BUFS(jId, t).destroy();
00313       }
00314 #endif
00315     }
00316   }
00317 
00318   if (cs)
00319   {
00320     cs->rebindPicBufs();
00321   }
00322 }
