00362 void Picture::finalInit( const VPS* vps, const SPS& sps, const PPS& pps, PicHeader *picHeader, APS** alfApss, APS* lmcsAps, APS* scalingListAps )
00363 {
00364   for( auto &sei : SEIs )
00365   {
00366     delete sei;
00367   }
00368   SEIs.clear();
00369   clearSliceBuffer();
00370 
00371   const ChromaFormat chromaFormatIDC = sps.getChromaFormatIdc();
00372   const int          iWidth = pps.getPicWidthInLumaSamples();
00373   const int          iHeight = pps.getPicHeightInLumaSamples();
00374 
00375   if( cs )
00376   {
00377     cs->initStructData();
00378   }
00379   else
00380   {
00381     cs = new CodingStructure( g_globalUnitCache.cuCache, g_globalUnitCache.puCache, g_globalUnitCache.tuCache );
00382     cs->sps = &sps;
00383     cs->create(chromaFormatIDC, Area(0, 0, iWidth, iHeight), true, (bool)sps.getPLTMode());
00384   }
00385 
00386   cs->vps = vps;
00387   cs->picture = this;
00388   cs->slice   = nullptr;  // the slices for this picture have not been set at this point. update cs->slice after swapSliceObject()
00389   cs->pps     = &pps;
00390   picHeader->setSPSId( sps.getSPSId() );
00391   picHeader->setPPSId( pps.getPPSId() );
00392   cs->picHeader = picHeader;
00393   memcpy(cs->alfApss, alfApss, sizeof(cs->alfApss));
00394   cs->lmcsAps = lmcsAps;
00395   cs->scalinglistAps = scalingListAps;
00396   cs->pcv     = pps.pcv;
00397   m_conformanceWindow = pps.getConformanceWindow();
00398   m_scalingWindow = pps.getScalingWindow();
00399 
00400   if (m_spliceIdx == NULL)
00401   {
00402     m_ctuNums = cs->pcv->sizeInCtus;
00403     m_spliceIdx = new int[m_ctuNums];
00404     memset(m_spliceIdx, 0, m_ctuNums * sizeof(int));
00405   }
00406 }
