00408 void Picture::allocateNewSlice()
00409 {
00410   slices.push_back(new Slice);
00411   Slice& slice = *slices.back();
00412   memcpy(slice.getAlfAPSs(), cs->alfApss, sizeof(cs->alfApss));
00413 
00414   slice.setPPS( cs->pps);
00415   slice.setSPS( cs->sps);
00416   slice.setVPS( cs->vps);
00417   if(slices.size()>=2)
00418   {
00419     slice.copySliceInfo( slices[slices.size()-2] );
00420     slice.initSlice();
00421   }
00422 }
00423 
00424 void Picture::fillSliceLossyLosslessArray(std::vector<uint16_t> sliceLosslessIndexArray, bool mixedLossyLossless)
00425 {
00426   uint16_t numElementsinsliceLosslessIndexArray = (uint16_t)sliceLosslessIndexArray.size();
00427   uint32_t numSlices = this->cs->pps->getNumSlicesInPic();
00428   m_lossylosslessSliceArray.assign(numSlices, true); // initialize to all slices are lossless 
00429   if (mixedLossyLossless)
00430   {
00431     m_lossylosslessSliceArray.assign(numSlices, false); // initialize to all slices are lossless 
00432     CHECK(numElementsinsliceLosslessIndexArray == 0 , "sliceLosslessArray is empty, must need to configure for mixed lossy/lossless");
00433 
00434     // mixed lossy/lossless slices, set only lossless slices;
00435     for (uint16_t i = 0; i < numElementsinsliceLosslessIndexArray; i++)
00436     {
00437         CHECK(sliceLosslessIndexArray[i] >= numSlices || sliceLosslessIndexArray[i] < 0, "index of lossless slice is out of slice index bound");
00438         m_lossylosslessSliceArray[sliceLosslessIndexArray[i]] = true;
00439     }
00440   } 
00441   CHECK(m_lossylosslessSliceArray.size() < numSlices, "sliceLosslessArray size is less than number of slices");
00442 }
00443 
00444 Slice *Picture::swapSliceObject(Slice * p, uint32_t i)
00445 {
00446   p->setSPS(cs->sps);
00447   p->setPPS(cs->pps);
00448   p->setVPS(cs->vps);
00449   p->setAlfAPSs(cs->alfApss);
00450 
00451 
00452   Slice * pTmp = slices[i];
00453   slices[i] = p;
00454   pTmp->setSPS(0);
00455   pTmp->setPPS(0);
00456   pTmp->setVPS(0);
00457   memset(pTmp->getAlfAPSs(), 0, sizeof(*pTmp->getAlfAPSs())*ALF_CTB_MAX_NUM_APS);
00458 
00459   return pTmp;
00460 }
