00471 #if ENABLE_SPLIT_PARALLELISM
00472 void Picture::finishParallelPart( const UnitArea& area )
00473 {
00474   const UnitArea clipdArea = clipArea( area, *this );
00475   const int      sourceID  = scheduler.getSplitPicId( 0 );
00476   CHECK( scheduler.getSplitJobId() > 0, "Finish-CU cannot be called from within a mode- or split-parallelized block!" );
00477 
00478   // distribute the reconstruction across all of the parallel workers
00479   for( int tId = 1; tId < scheduler.getNumSplitThreads(); tId++ )
00480   {
00481     const int destID = scheduler.getSplitPicId( tId );
00482 
00483     M_BUFS( destID, PIC_RECONSTRUCTION ).subBuf( clipdArea ).copyFrom( M_BUFS( sourceID, PIC_RECONSTRUCTION ).subBuf( clipdArea ) );
00484   }
00485 }
00486 #endif
