00640 void Picture::sampleRateConv( const std::pair<int, int> scalingRatio, const std::pair<int, int> compScale,
00641                               const CPelBuf& beforeScale, const int beforeScaleLeftOffset, const int beforeScaleTopOffset,
00642                               const PelBuf& afterScale, const int afterScaleLeftOffset, const int afterScaleTopOffset,
00643                               const int bitDepth, const bool useLumaFilter, const bool downsampling,
00644                               const bool horCollocatedPositionFlag, const bool verCollocatedPositionFlag )
00645 {
00646   const Pel* orgSrc = beforeScale.buf;
00647   const int orgWidth = beforeScale.width;
00648   const int orgHeight = beforeScale.height;
00649   const int orgStride = beforeScale.stride;
00650 
00651   Pel* scaledSrc = afterScale.buf;
00652   const int scaledWidth = afterScale.width;
00653   const int scaledHeight = afterScale.height;
00654   const int scaledStride = afterScale.stride;
00655 
00656   if( orgWidth == scaledWidth && orgHeight == scaledHeight && scalingRatio == SCALE_1X && !beforeScaleLeftOffset && !beforeScaleTopOffset && !afterScaleLeftOffset && !afterScaleTopOffset )
00657   {
00658     for( int j = 0; j < orgHeight; j++ )
00659     {
00660       memcpy( scaledSrc + j * scaledStride, orgSrc + j * orgStride, sizeof( Pel ) * orgWidth );
00661     }
00662 
00663     return;
00664   }
00665 
00666   const TFilterCoeff* filterHor = useLumaFilter ? &InterpolationFilter::m_lumaFilter[0][0] : &InterpolationFilter::m_chromaFilter[0][0];
00667   const TFilterCoeff* filterVer = useLumaFilter ? &InterpolationFilter::m_lumaFilter[0][0] : &InterpolationFilter::m_chromaFilter[0][0];
00668   const int numFracPositions = useLumaFilter ? 15 : 31;
00669   const int numFracShift = useLumaFilter ? 4 : 5;
00670   const int posShiftX = SCALE_RATIO_BITS - numFracShift + compScale.first;
00671   const int posShiftY = SCALE_RATIO_BITS - numFracShift + compScale.second;
00672   int addX = ( 1 << ( posShiftX - 1 ) ) + ( beforeScaleLeftOffset << SCALE_RATIO_BITS ) + ( ( int( 1 - horCollocatedPositionFlag ) * 8 * ( scalingRatio.first - SCALE_1X.first ) + ( 1 << ( 2 + compScale.first ) ) ) >> ( 3 + compScale.first ) );
00673   int addY = ( 1 << ( posShiftY - 1 ) ) + ( beforeScaleTopOffset << SCALE_RATIO_BITS ) + ( ( int( 1 - verCollocatedPositionFlag ) * 8 * ( scalingRatio.second - SCALE_1X.second ) + ( 1 << ( 2 + compScale.second ) ) ) >> ( 3 + compScale.second ) );
00674 
00675   if( downsampling )
00676   {
00677     int verFilter = 0;
00678     int horFilter = 0;
00679 
00680     if (scalingRatio.first > (15 << SCALE_RATIO_BITS) / 4)
00681     {
00682       horFilter = 7;
00683     }
00684     else if (scalingRatio.first > (20 << SCALE_RATIO_BITS) / 7)
00685     {
00686       horFilter = 6;
00687     }
00688     else if (scalingRatio.first > (5 << SCALE_RATIO_BITS) / 2)
00689     {
00690       horFilter = 5;
00691     }
00692     else if (scalingRatio.first > (2 << SCALE_RATIO_BITS))
00693     {
00694       horFilter = 4;
00695     }
00696     else if (scalingRatio.first > (5 << SCALE_RATIO_BITS) / 3)
00697     {
00698       horFilter = 3;
00699     }
00700     else if (scalingRatio.first > (5 << SCALE_RATIO_BITS) / 4)
00701     {
00702       horFilter = 2;
00703     }
00704     else if (scalingRatio.first > (20 << SCALE_RATIO_BITS) / 19)
00705     {
00706       horFilter = 1;
00707     }
00708 
00709     if (scalingRatio.second > (15 << SCALE_RATIO_BITS) / 4)
00710     {
00711       verFilter = 7;
00712     }
00713     else if (scalingRatio.second > (20 << SCALE_RATIO_BITS) / 7)
00714     {
00715       verFilter = 6;
00716     }
00717     else if (scalingRatio.second > (5 << SCALE_RATIO_BITS) / 2)
00718     {
00719       verFilter = 5;
00720     }
00721     else if (scalingRatio.second > (2 << SCALE_RATIO_BITS))
00722     {
00723       verFilter = 4;
00724     }
00725     else if (scalingRatio.second > (5 << SCALE_RATIO_BITS) / 3)
00726     {
00727       verFilter = 3;
00728     }
00729     else if (scalingRatio.second > (5 << SCALE_RATIO_BITS) / 4)
00730     {
00731       verFilter = 2;
00732     }
00733     else if (scalingRatio.second > (20 << SCALE_RATIO_BITS) / 19)
00734     {
00735       verFilter = 1;
00736     }
00737 
00738     filterHor = &DownsamplingFilterSRC[horFilter][0][0];
00739     filterVer = &DownsamplingFilterSRC[verFilter][0][0];
00740   }
00741 
00742   const int filterLength = downsampling ? 12 : ( useLumaFilter ? NTAPS_LUMA : NTAPS_CHROMA );
00743   const int log2Norm = downsampling ? 14 : 12;
00744 
00745   int *buf = new int[orgHeight * scaledWidth];
00746   int maxVal = ( 1 << bitDepth ) - 1;
00747 
00748   CHECK( bitDepth > 17, "Overflow may happen!" );
00749 
00750   for( int i = 0; i < scaledWidth; i++ )
00751   {
00752     const Pel* org = orgSrc;
00753     int refPos = ( ( ( i << compScale.first ) - afterScaleLeftOffset ) * scalingRatio.first + addX ) >> posShiftX;
00754     int integer = refPos >> numFracShift;
00755     int frac = refPos & numFracPositions;
00756     int* tmp = buf + i;
00757 
00758     for( int j = 0; j < orgHeight; j++ )
00759     {
00760       int sum = 0;
00761       const TFilterCoeff* f = filterHor + frac * filterLength;
00762 
00763       for( int k = 0; k < filterLength; k++ )
00764       {
00765         int xInt = std::min<int>( std::max( 0, integer + k - filterLength / 2 + 1 ), orgWidth - 1 );
00766         sum += f[k] * org[xInt]; // postpone horizontal filtering gain removal after vertical filtering
00767       }
00768 
00769       *tmp = sum;
00770 
00771       tmp += scaledWidth;
00772       org += orgStride;
00773     }
00774   }
00775 
00776   Pel* dst = scaledSrc;
00777 
00778   for( int j = 0; j < scaledHeight; j++ )
00779   {
00780     int refPos = ( ( ( j << compScale.second ) - afterScaleTopOffset ) * scalingRatio.second + addY ) >> posShiftY;
00781     int integer = refPos >> numFracShift;
00782     int frac = refPos & numFracPositions;
00783 
00784     for( int i = 0; i < scaledWidth; i++ )
00785     {
00786       int sum = 0;
00787       int* tmp = buf + i;
00788       const TFilterCoeff* f = filterVer + frac * filterLength;
00789 
00790       for( int k = 0; k < filterLength; k++ )
00791       {
00792         int yInt = std::min<int>( std::max( 0, integer + k - filterLength / 2 + 1 ), orgHeight - 1 );
00793         sum += f[k] * tmp[yInt*scaledWidth];
00794       }
00795 
00796       dst[i] = std::min<int>( std::max( 0, ( sum + ( 1 << ( log2Norm - 1 ) ) ) >> log2Norm ), maxVal );
00797     }
00798 
00799     dst += scaledStride;
00800   }
00801 
00802   delete[] buf;
00803 }
00804 
00805 void Picture::rescalePicture( const std::pair<int, int> scalingRatio,
00806                               const CPelUnitBuf& beforeScaling, const Window& scalingWindowBefore,
00807                               const PelUnitBuf& afterScaling, const Window& scalingWindowAfter,
00808                               const ChromaFormat chromaFormatIDC, const BitDepths& bitDepths, const bool useLumaFilter, const bool downsampling,
00809                               const bool horCollocatedChromaFlag, const bool verCollocatedChromaFlag )
00810 {
00811   for( int comp = 0; comp < vtm::getNumberValidComponents( chromaFormatIDC ); comp++ )
00812   {
00813     ComponentID compID = ComponentID( comp );
00814     const CPelBuf& beforeScale = beforeScaling.get( compID );
00815     const PelBuf& afterScale = afterScaling.get( compID );
00816 
00817     sampleRateConv( scalingRatio, std::pair<int, int>( vtm::getComponentScaleX( compID, chromaFormatIDC ), vtm::getComponentScaleY( compID, chromaFormatIDC ) ),
00818                     beforeScale, scalingWindowBefore.getWindowLeftOffset() * SPS::getWinUnitX( chromaFormatIDC ), scalingWindowBefore.getWindowTopOffset() * SPS::getWinUnitY( chromaFormatIDC ),
00819                     afterScale, scalingWindowAfter.getWindowLeftOffset() * SPS::getWinUnitX( chromaFormatIDC ), scalingWindowAfter.getWindowTopOffset() * SPS::getWinUnitY( chromaFormatIDC ),
00820                     bitDepths.recon[toChannelType(compID)], downsampling || useLumaFilter ? true : isLuma( compID ), downsampling,
00821                     isLuma( compID ) ? 1 : horCollocatedChromaFlag, isLuma( compID ) ? 1 : verCollocatedChromaFlag );
00822   }
00823 }
00824 
00825 void Picture::saveSubPicBorder(int POC, int subPicX0, int subPicY0, int subPicWidth, int subPicHeight)
00826 {
00827 
00828   // 1.1 set up margin for back up memory allocation
00829   int xMargin = margin >> getComponentScaleX(COMPONENT_Y, cs->area.chromaFormat);
00830   int yMargin = margin >> getComponentScaleY(COMPONENT_Y, cs->area.chromaFormat);
00831 
00832   // 1.2 measure the size of back up memory
00833   Area areaAboveBelow(0, 0, subPicWidth + 2 * xMargin, yMargin);
00834   Area areaLeftRight(0, 0, xMargin, subPicHeight);
00835   UnitArea unitAreaAboveBelow(cs->area.chromaFormat, areaAboveBelow);
00836   UnitArea unitAreaLeftRight(cs->area.chromaFormat, areaLeftRight);
00837 
00838   // 1.3 create back up memory
00839   m_bufSubPicAbove.create(unitAreaAboveBelow);
00840   m_bufSubPicBelow.create(unitAreaAboveBelow);
00841   m_bufSubPicLeft.create(unitAreaLeftRight);
00842   m_bufSubPicRight.create(unitAreaLeftRight);
00843   m_bufWrapSubPicAbove.create(unitAreaAboveBelow);
00844   m_bufWrapSubPicBelow.create(unitAreaAboveBelow);
00845 
00846   for (int comp = 0; comp < getNumberValidComponents(cs->area.chromaFormat); comp++)
00847   {
00848     ComponentID compID = ComponentID(comp);
00849 
00850     // 2.1 measure the margin for each component
00851     int xmargin = margin >> getComponentScaleX(compID, cs->area.chromaFormat);
00852     int ymargin = margin >> getComponentScaleY(compID, cs->area.chromaFormat);
00853 
00854     // 2.2 calculate the origin of the subpicture
00855     int left = subPicX0 >> getComponentScaleX(compID, cs->area.chromaFormat);
00856     int top = subPicY0 >> getComponentScaleY(compID, cs->area.chromaFormat);
00857 
00858     // 2.3 calculate the width/height of the subPic
00859     int width = subPicWidth >> getComponentScaleX(compID, cs->area.chromaFormat);
00860     int height = subPicHeight >> getComponentScaleY(compID, cs->area.chromaFormat);
00861 
00862 
00863     // 3.1.1 set reconstructed picture
00864     PelBuf s = M_BUFS(0, PIC_RECONSTRUCTION).get(compID);
00865     Pel *src = s.bufAt(left, top);
00866 
00867     // 3.2.1 set back up buffer for left
00868     PelBuf dBufLeft   = m_bufSubPicLeft.getBuf(compID);
00869     Pel    *dstLeft   = dBufLeft.bufAt(0, 0);
00870 
00871 
00872     // 3.2.2 set back up buffer for right
00873     PelBuf dBufRight  = m_bufSubPicRight.getBuf(compID);
00874     Pel    *dstRight  = dBufRight.bufAt(0, 0);
00875 
00876     // 3.2.3 copy to recon picture to back up buffer
00877     Pel *srcLeft  = src - xmargin;
00878     Pel *srcRight = src + width;
00879     for (int y = 0; y < height; y++)
00880     {
00881       ::memcpy(dstLeft  + y *  dBufLeft.stride, srcLeft  + y * s.stride, sizeof(Pel) * xmargin);
00882       ::memcpy(dstRight + y * dBufRight.stride, srcRight + y * s.stride, sizeof(Pel) * xmargin);
00883     }
00884 
00885     // 3.3.1 set back up buffer for above
00886     PelBuf dBufTop = m_bufSubPicAbove.getBuf(compID);
00887     Pel    *dstTop = dBufTop.bufAt(0, 0);
00888 
00889     // 3.3.2 set back up buffer for below
00890     PelBuf dBufBottom = m_bufSubPicBelow.getBuf(compID);
00891     Pel    *dstBottom = dBufBottom.bufAt(0, 0);
00892 
00893     // 3.3.3 copy to recon picture to back up buffer
00894     Pel *srcTop    = src - xmargin - ymargin * s.stride;
00895     Pel *srcBottom = src - xmargin +  height * s.stride;
00896     for (int y = 0; y < ymargin; y++)
00897     {
00898       ::memcpy(dstTop    + y *    dBufTop.stride, srcTop    + y * s.stride, sizeof(Pel) * (2 * xmargin + width));
00899       ::memcpy(dstBottom + y * dBufBottom.stride, srcBottom + y * s.stride, sizeof(Pel) * (2 * xmargin + width));
00900     }
00901 
00902     // back up recon wrap buffer
00903     if (cs->sps->getWrapAroundEnabledFlag())
00904     {
00905       PelBuf sWrap = M_BUFS(0, PIC_RECON_WRAP).get(compID);
00906       Pel *srcWrap = sWrap.bufAt(left, top);
00907 
00908       // 3.4.1 set back up buffer for above
00909       PelBuf dBufTopWrap = m_bufWrapSubPicAbove.getBuf(compID);
00910       Pel    *dstTopWrap = dBufTopWrap.bufAt(0, 0);
00911 
00912       // 3.4.2 set back up buffer for below
00913       PelBuf dBufBottomWrap = m_bufWrapSubPicBelow.getBuf(compID);
00914       Pel    *dstBottomWrap = dBufBottomWrap.bufAt(0, 0);
00915 
00916       // 3.4.3 copy recon wrap picture to back up buffer
00917       Pel *srcTopWrap    = srcWrap - xmargin - ymargin * sWrap.stride;
00918       Pel *srcBottomWrap = srcWrap - xmargin +  height * sWrap.stride;
00919       for (int y = 0; y < ymargin; y++)
00920       {
00921         ::memcpy(dstTopWrap    + y *    dBufTopWrap.stride, srcTopWrap    + y * sWrap.stride, sizeof(Pel) * (2 * xmargin + width));
00922         ::memcpy(dstBottomWrap + y * dBufBottomWrap.stride, srcBottomWrap + y * sWrap.stride, sizeof(Pel) * (2 * xmargin + width));
00923       }
00924     }
00925   }
00926 }
00927 
00928 void Picture::extendSubPicBorder(int POC, int subPicX0, int subPicY0, int subPicWidth, int subPicHeight)
00929 {
00930 
00931   for (int comp = 0; comp < getNumberValidComponents(cs->area.chromaFormat); comp++)
00932   {
00933     ComponentID compID = ComponentID(comp);
00934 
00935     // 2.1 measure the margin for each component
00936     int xmargin = margin >> getComponentScaleX(compID, cs->area.chromaFormat);
00937     int ymargin = margin >> getComponentScaleY(compID, cs->area.chromaFormat);
00938 
00939     // 2.2 calculate the origin of the Subpicture
00940     int left = subPicX0 >> getComponentScaleX(compID, cs->area.chromaFormat);
00941     int top = subPicY0 >> getComponentScaleY(compID, cs->area.chromaFormat);
00942 
00943     // 2.3 calculate the width/height of the Subpicture
00944     int width = subPicWidth >> getComponentScaleX(compID, cs->area.chromaFormat);
00945     int height = subPicHeight >> getComponentScaleY(compID, cs->area.chromaFormat);
00946 
00947     // 3.1 set reconstructed picture
00948     PelBuf s = M_BUFS(0, PIC_RECONSTRUCTION).get(compID);
00949     Pel *src = s.bufAt(left, top);
00950 
00951     // 4.1 apply padding for left and right
00952     {
00953       Pel *dstLeft  = src - xmargin;
00954       Pel *dstRight = src + width;
00955       Pel *srcLeft  = src + 0;
00956       Pel *srcRight = src + width - 1;
00957 
00958       for (int y = 0; y < height; y++)
00959       {
00960         for (int x = 0; x < xmargin; x++)
00961         {
00962           dstLeft[x]  = *srcLeft;
00963           dstRight[x] = *srcRight;
00964         }
00965         dstLeft += s.stride;
00966         dstRight += s.stride;
00967         srcLeft += s.stride;
00968         srcRight += s.stride;
00969       }
00970     }
00971 
00972     // 4.2 apply padding on bottom
00973     Pel *srcBottom = src + s.stride * (height - 1) - xmargin;
00974     Pel *dstBottom = srcBottom + s.stride;
00975     for (int y = 0; y < ymargin; y++)
00976     {
00977       ::memcpy(dstBottom, srcBottom, sizeof(Pel)*(2 * xmargin + width));
00978       dstBottom += s.stride;
00979     }
00980 
00981     // 4.3 apply padding for top
00982     // si is still (-marginX, SubpictureHeight-1)
00983     Pel *srcTop = src - xmargin;
00984     Pel *dstTop = srcTop - s.stride;
00985     // si is now (-marginX, 0)
00986     for (int y = 0; y < ymargin; y++)
00987     {
00988       ::memcpy(dstTop, srcTop, sizeof(Pel)*(2 * xmargin + width));
00989       dstTop -= s.stride;
00990     }
00991 
00992     // Appy padding for recon wrap buffer
00993     if (cs->sps->getWrapAroundEnabledFlag())
00994     {
00995       // set recon wrap picture
00996       PelBuf sWrap = M_BUFS(0, PIC_RECON_WRAP).get(compID);
00997       Pel *srcWrap = sWrap.bufAt(left, top);
00998 
00999       // apply padding on bottom
01000       Pel *srcBottomWrap = srcWrap + sWrap.stride * (height - 1) - xmargin;
01001       Pel *dstBottomWrap = srcBottomWrap + sWrap.stride;
01002       for (int y = 0; y < ymargin; y++)
01003       {
01004         ::memcpy(dstBottomWrap, srcBottomWrap, sizeof(Pel)*(2 * xmargin + width));
01005         dstBottomWrap += sWrap.stride;
01006       }
01007 
01008       // apply padding for top
01009       // si is still (-marginX, SubpictureHeight-1)
01010       Pel *srcTopWrap = srcWrap - xmargin;
01011       Pel *dstTopWrap = srcTopWrap - sWrap.stride;
01012       // si is now (-marginX, 0)
01013       for (int y = 0; y < ymargin; y++)
01014       {
01015         ::memcpy(dstTopWrap, srcTopWrap, sizeof(Pel)*(2 * xmargin + width));
01016         dstTopWrap -= sWrap.stride;
01017       }
01018     }
01019   } // end of for
01020 }
01021 
01022 void Picture::restoreSubPicBorder(int POC, int subPicX0, int subPicY0, int subPicWidth, int subPicHeight)
01023 {
01024   for (int comp = 0; comp < getNumberValidComponents(cs->area.chromaFormat); comp++)
01025   {
01026     ComponentID compID = ComponentID(comp);
01027 
01028     // 2.1 measure the margin for each component
01029     int xmargin = margin >> getComponentScaleX(compID, cs->area.chromaFormat);
01030     int ymargin = margin >> getComponentScaleY(compID, cs->area.chromaFormat);
01031 
01032     // 2.2 calculate the origin of the subpicture
01033     int left = subPicX0 >> getComponentScaleX(compID, cs->area.chromaFormat);
01034     int top = subPicY0 >> getComponentScaleY(compID, cs->area.chromaFormat);
01035 
01036     // 2.3 calculate the width/height of the subpicture
01037     int width = subPicWidth >> getComponentScaleX(compID, cs->area.chromaFormat);
01038     int height = subPicHeight >> getComponentScaleY(compID, cs->area.chromaFormat);
01039 
01040     // 3.1 set reconstructed picture
01041     PelBuf s = M_BUFS(0, PIC_RECONSTRUCTION).get(compID);
01042     Pel *src = s.bufAt(left, top);
01043 
01044     // 4.2.1 copy from back up buffer to recon picture
01045     PelBuf dBufLeft = m_bufSubPicLeft.getBuf(compID);
01046     Pel    *dstLeft = dBufLeft.bufAt(0, 0);
01047 
01048     // 4.2.2 set back up buffer for right
01049     PelBuf dBufRight = m_bufSubPicRight.getBuf(compID);
01050     Pel    *dstRight = dBufRight.bufAt(0, 0);
01051 
01052     // 4.2.3 copy to recon picture to back up buffer
01053     Pel *srcLeft  = src - xmargin;
01054     Pel *srcRight = src + width;
01055 
01056     for (int y = 0; y < height; y++)
01057     {
01058       // the destination and source position is reversed on purpose
01059       ::memcpy(srcLeft  + y * s.stride,  dstLeft + y *  dBufLeft.stride, sizeof(Pel) * xmargin);
01060       ::memcpy(srcRight + y * s.stride, dstRight + y * dBufRight.stride, sizeof(Pel) * xmargin);
01061     }
01062 
01063 
01064     // 4.3.1 set back up buffer for above
01065     PelBuf dBufTop = m_bufSubPicAbove.getBuf(compID);
01066     Pel    *dstTop = dBufTop.bufAt(0, 0);
01067 
01068     // 4.3.2 set back up buffer for below
01069     PelBuf dBufBottom = m_bufSubPicBelow.getBuf(compID);
01070     Pel    *dstBottom = dBufBottom.bufAt(0, 0);
01071 
01072     // 4.3.3 copy to recon picture to back up buffer
01073     Pel *srcTop = src - xmargin - ymargin * s.stride;
01074     Pel *srcBottom = src - xmargin + height * s.stride;
01075 
01076     for (int y = 0; y < ymargin; y++)
01077     {
01078       ::memcpy(srcTop    + y * s.stride, dstTop    + y *    dBufTop.stride, sizeof(Pel) * (2 * xmargin + width));
01079       ::memcpy(srcBottom + y * s.stride, dstBottom + y * dBufBottom.stride, sizeof(Pel) * (2 * xmargin + width));
01080     }
01081 
01082     // restore recon wrap buffer
01083     if (cs->sps->getWrapAroundEnabledFlag())
01084     {
01085       // set recon wrap picture
01086       PelBuf sWrap = M_BUFS(0, PIC_RECON_WRAP).get(compID);
01087       Pel *srcWrap = sWrap.bufAt(left, top);
01088 
01089       // set back up buffer for above
01090       PelBuf dBufTopWrap = m_bufWrapSubPicAbove.getBuf(compID);
01091       Pel    *dstTopWrap = dBufTopWrap.bufAt(0, 0);
01092 
01093       // set back up buffer for below
01094       PelBuf dBufBottomWrap = m_bufWrapSubPicBelow.getBuf(compID);
01095       Pel    *dstBottomWrap = dBufBottomWrap.bufAt(0, 0);
01096 
01097       // copy to recon wrap picture from back up buffer
01098       Pel *srcTopWrap = srcWrap - xmargin - ymargin * sWrap.stride;
01099       Pel *srcBottomWrap = srcWrap - xmargin + height * sWrap.stride;
01100 
01101       for (int y = 0; y < ymargin; y++)
01102       {
01103         ::memcpy(srcTopWrap    + y * sWrap.stride, dstTopWrap    + y *    dBufTopWrap.stride, sizeof(Pel) * (2 * xmargin + width));
01104         ::memcpy(srcBottomWrap + y * sWrap.stride, dstBottomWrap + y * dBufBottomWrap.stride, sizeof(Pel) * (2 * xmargin + width));
01105       }
01106     }
01107   }
01108 
01109   // 5.0 destroy the back up memory
01110   m_bufSubPicAbove.destroy();
01111   m_bufSubPicBelow.destroy();
01112   m_bufSubPicLeft.destroy();
01113   m_bufSubPicRight.destroy();
01114   m_bufWrapSubPicAbove.destroy();
01115   m_bufWrapSubPicBelow.destroy();
01116 }
01117 
01118 void Picture::extendPicBorder( const PPS *pps )
01119 {
01120   if ( m_bIsBorderExtended )
01121   {
01122     if( isWrapAroundEnabled( pps ) && ( !m_wrapAroundValid || m_wrapAroundOffset != pps->getWrapAroundOffset() ) )
01123     {
01124       extendWrapBorder( pps );
01125     }
01126     return;
01127   }
01128 
01129   for(int comp=0; comp<getNumberValidComponents( cs->area.chromaFormat ); comp++)
01130   {
01131     ComponentID compID = ComponentID( comp );
01132     PelBuf p = M_BUFS( 0, PIC_RECONSTRUCTION ).get( compID );
01133     Pel *piTxt = p.bufAt(0,0);
01134     int xmargin = margin >> getComponentScaleX( compID, cs->area.chromaFormat );
01135     int ymargin = margin >> getComponentScaleY( compID, cs->area.chromaFormat );
01136 
01137     Pel*  pi = piTxt;
01138     // do left and right margins
01139     for (int y = 0; y < p.height; y++)
01140     {
01141       for (int x = 0; x < xmargin; x++)
01142       {
01143         pi[-xmargin + x] = pi[0];
01144         pi[p.width + x]  = pi[p.width - 1];
01145       }
01146       pi += p.stride;
01147     }
01148 
01149     // pi is now the (0,height) (bottom left of image within bigger picture
01150     pi -= (p.stride + xmargin);
01151     // pi is now the (-marginX, height-1)
01152     for (int y = 0; y < ymargin; y++ )
01153     {
01154       ::memcpy( pi + (y+1)*p.stride, pi, sizeof(Pel)*(p.width + (xmargin << 1)));
01155     }
01156 
01157     // pi is still (-marginX, height-1)
01158     pi -= ((p.height-1) * p.stride);
01159     // pi is now (-marginX, 0)
01160     for (int y = 0; y < ymargin; y++ )
01161     {
01162       ::memcpy( pi - (y+1)*p.stride, pi, sizeof(Pel)*(p.width + (xmargin<<1)) );
01163     }
01164 
01165     // reference picture with horizontal wrapped boundary
01166     if ( isWrapAroundEnabled( pps ) )
01167     {
01168       extendWrapBorder( pps );
01169     }
01170     else
01171     {
01172       m_wrapAroundValid = false;
01173       m_wrapAroundOffset = 0;
01174     }
01175   }
01176 
01177   m_bIsBorderExtended = true;
01178 }
01179 
01180 void Picture::extendWrapBorder( const PPS *pps )
01181 {
01182   for(int comp=0; comp<getNumberValidComponents( cs->area.chromaFormat ); comp++)
01183   {
01184     ComponentID compID = ComponentID( comp );
01185     PelBuf p = M_BUFS( 0, PIC_RECON_WRAP ).get( compID );
01186     p.copyFrom(M_BUFS( 0, PIC_RECONSTRUCTION ).get( compID ));
01187     Pel *piTxt = p.bufAt(0,0);
01188     int xmargin = margin >> getComponentScaleX( compID, cs->area.chromaFormat );
01189     int ymargin = margin >> getComponentScaleY( compID, cs->area.chromaFormat );
01190     Pel*  pi = piTxt;
01191     int xoffset = pps->getWrapAroundOffset() >> getComponentScaleX( compID, cs->area.chromaFormat );
01192     for (int y = 0; y < p.height; y++)
01193     {
01194       for (int x = 0; x < xmargin; x++ )
01195       {
01196         if( x < xoffset )
01197         {
01198           pi[ -x - 1 ] = pi[ -x - 1 + xoffset ];
01199           pi[  p.width + x ] = pi[ p.width + x - xoffset ];
01200         }
01201         else
01202         {
01203           pi[ -x - 1 ] = pi[ 0 ];
01204           pi[  p.width + x ] = pi[ p.width - 1 ];
01205         }
01206       }
01207       pi += p.stride;
01208     }
01209     pi -= (p.stride + xmargin);
01210     for (int y = 0; y < ymargin; y++ )
01211     {
01212       ::memcpy( pi + (y+1)*p.stride, pi, sizeof(Pel)*(p.width + (xmargin << 1)));
01213     }
01214     pi -= ((p.height-1) * p.stride);
01215     for (int y = 0; y < ymargin; y++ )
01216     {
01217       ::memcpy( pi - (y+1)*p.stride, pi, sizeof(Pel)*(p.width + (xmargin<<1)) );
01218     }
01219   }
01220   m_wrapAroundValid = true;
01221   m_wrapAroundOffset = pps->getWrapAroundOffset();
01222 }
